// 模块：edge_gateway/main.go
// 功能：工业边缘网关主入口 — 多协议接入 + 双通道消息路由
// 依赖：go.mod: github.com/eclipse/paho.mqtt.golang v1.4.3
//                         confluentinc/confluent-kafka-go v1.9.2
//                        ModernC/go-sqlite3 v1.14.24
// ============================================================

package main

import (
	"context"
	"encoding/binary"
	"fmt"
	"log"
	"math/rand"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	mqtt "github.com/eclipse/paho.mqtt.golang"
	"github.com/confluentinc/confluent-kafka-go/kafka"
	"github.com/mattn/go-sqlite3"
)

// ----------------------------------------------------------
// 配置结构：从环境变量或配置文件注入，生产环境建议使用Viper
// ----------------------------------------------------------
type GatewayConfig struct {
	// 设备驱动配置
	SerialPort   string `env:"SERIAL_PORT" default:"/dev/ttyUSB0"`
	BaudRate     int    `env:"BAUD_RATE" default:"115200"`
	ModbusUnitID int    `env:"MODBUS_UNIT_ID" default:"1"`

	// MQTT Broker 配置（EMQX集群）
	MQTTBroker   string `env:"MQTT_BROKER" default:"tcp://192.168.1.100:1883"`
	MQTTClientID string `env:"MQTT_CLIENT_ID" default:"gw-edge-001"`
	MQTTPersistence bool `env:"MQTT_PERSISTENCE" default:"true"`

	// Kafka 集群配置
	KafkaBrokers string `env:"KAFKA_BROKERS" default:"192.168.1.200:9092,192.168.1.201:9092"`
	KafkaTopic   string `env:"KAFKA_TOPIC" default:"iot.telemetry.raw"`

	// 本地缓存配置
	CacheDBPath  string `env:"CACHE_DB_PATH" default:"/data/gateway/cache.db"`
	CacheMaxRows int    `env:"CACHE_MAX_ROWS" default:"50000"` // 超限后 oldest 数据自动清理

	// 背压阈值（Kafka consumer lag）
	BackpressureThreshold int `env:"BACKPRESSURE_THRESHOLD" default:"5000"`
}

// ----------------------------------------------------------
// 设备遥测数据模型
// topic 格式: iot/{device_type}/{device_id}/telemetry
// ----------------------------------------------------------
type TelemetryPacket struct {
	DeviceID    string    `json:"device_id"`
	DeviceType  string    `json:"device_type"`
	Timestamp   int64     `json:"ts"`          // Unix纳秒时间戳
	Readings    []Reading `json:"readings"`    // 键值对测点集合
	Checksum    uint32    `json:"crc32"`       // 用于完整性校验
	SeqNo       uint64    `json:"seq_no"`      // 单调递增序列号，用于去重
}

type Reading struct {
	PointName string  `json:"name"`
	Value     float64 `json:"value"`
	Quality   int8    `json:"quality"` // 1=GOOD, 0=BAD, -1=UNCERTAIN
}

// ----------------------------------------------------------
// 边缘网关核心引擎
// ----------------------------------------------------------
type EdgeGateway struct {
	cfg     GatewayConfig
	wg      sync.WaitGroup

	// 本地SQLite持久化（断网缓存）
	cacheDB *sql.DB

	// MQTT客户端（EMQX通道）
	mqttClient mqtt.Client

	// Kafka生产者（高吞吐通道）
	kafkaProducer *kafka.Producer

	// 背压状态机
