	seqMu      sync.Mutex

	// 串口读写buffer，避免频繁分配
	modbusBuffer [4096]byte
}

func NewGateway(cfg GatewayConfig) (*EdgeGateway, error) {
	gw := &EdgeGateway{cfg: cfg}

	// 初始化本地SQLite缓存（WAL模式提升并发写入性能）
	db, err := sqlite3.Open(cfg.CacheDBPath)
	if err != nil {
		return nil, fmt.Errorf("打开缓存数据库失败: %w", err)
	}
	db.SetMaxOpenConns(4) // SQLite写锁竞争，限制并发连接数
	db.Exec("PRAGMA journal_mode=WAL")
	db.Exec("PRAGMA synchronous=NORMAL") // 平衡性能与安全，允许最多丢失最后一个事务

	// 建表：telemetry_cache 使用IF NOT EXISTS保证幂等
