		"compression.type":  "snappy",          // Snappy压缩，节省带宽
		"queue.buffering.max.messages": 100000, // 批量聚合阈值
		"linger.ms":         10,                // 最大等待时间(ms)
		"retry.count":       5,
		"delivery.timeout.ms": 30000,
	})
	if err != nil {
		return nil, fmt.Errorf("初始化Kafka生产者失败: %w", err)
	}
	gw.kafkaProducer = producer

	return gw, nil
}

