## 三、工业级生产环境完整实现代码示例

以下是我们在产线实际部署的 Go 语言实现，包含串口驱动、持久化缓存、断网续传三大核心模块。

### 3.1 串口驱动层（带时钟漂移补偿）

```go
package serial

import (
	"fmt"
	"log"
	"os"
	"sync"
	"time"

	"github.com/tarm/goserial"
)

// SerialDriver 工业级串口驱动，支持时钟漂移自动补偿
type SerialDriver struct {
	port     *serial.Port
	mu       sync.RWMutex
	baudRate int
	// 漂移补偿参数
	avgDrift float64
	driftMu  sync.Mutex
}

// NewSerialDriver 创建带自适应波特率补偿的串口驱动
func NewSerialDriver(portName string, baud int) (*SerialDriver, error) {
	// 优先尝试常见工业串口名称
	config := &serial.Config{
		Name:        portName,
		Baud:        baud,
		ReadTimeout: 500 * time.Millisecond,
	}

	port, err := serial.OpenPort(config)
	if err != nil {
		return nil, fmt.Errorf("打开串口 %s 失败: %v", portName, err)
	}

	// 设置 RTS/CTS 硬件流控，避免缓冲区溢出
	port.SetRTS(true)
	port.SetCTS(true)

	driver := &SerialDriver{
		port:     port,
		baudRate: baud,
	}

	// 启动后台漂移监测协程
	go driver.driftMonitor()

	log.Printf("[Serial] 驱动初始化完成: %s @ %d baud", portName, baud)
	return driver, nil
}

// driftMonitor 实时监测波特率漂移并自动补偿
func (d *SerialDriver) driftMonitor() {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		// 统计最近一批数据的 CRC 错误率
		errorRate := d.calculateErrorRate()
		if errorRate > 0.001 { // 超过 0.1% 误码率触发补偿
			d.driftMu.Lock()
			d.avgDrift = errorRate * 1000 // 转换为 ppm
			d.driftMu.Unlock()

			// 自动调整波特率 ±1%
			adjustedBaud := d.baudRate * (1 - d.avgDrift/1000000)
			d.port.Close()
			d.port, _ = serial.OpenPort(&serial.Config{
				Name:        d.port.Name,
				Baud:        int(adjustedBaud),
				ReadTimeout: 500 * time.Millisecond,
			})
			log.Printf("[Serial] 检测到漂移 %.2f ppm，已调整波特率为 %d", 
				d.avgDrift, int(adjustedBaud))
		}
	}
}

// ReadFrame 读取一帧完整数据，处理粘连帧与反射干扰
func (d *SerialDriver) ReadFrame() ([]byte, error) {
	d.mu.RLock()
	defer d.mu.RUnlock()

	var buffer []byte
	startTime := time.Now()
	maxWait := 100 * time.Millisecond

	for {
		if time.Since(startTime) > maxWait {
			return nil, fmt.Errorf("帧读取超时")
		}

		// 非阻塞读取
		data := make([]byte, 256)
		n, err := d.port.Read(data)
		if err != nil {
			if err == os.ErrDeadlineExceeded {
				continue
			}
			return nil, err
		}

		buffer = append(buffer, data[:n]...)

		// 检测帧结束符 (Modbus RTU 无间隔超时)
		if len(buffer) >= 4 && isFrameComplete(buffer) {
			return d.validateFrame(buffer)
		}
	}
}

// validateFrame 校验帧完整性，处理反射粘连
func (d *SerialDriver) validateFrame(raw []byte) ([]byte, error) {
	// CRC16 校验
	if !checkCRC16(raw) {
		return nil, fmt.Errorf("CRC 校验失败，疑似信号反射")
	}

	// 去除可能的反射重复字节
	cleaned := removeReflectionDuplicates(raw)
	return cleaned, nil
}
