// DataBuffer 断网续传缓冲区
type DataBuffer struct {
	db     *sql.DB
	mu     sync.Mutex
	batch  [][]interface{}
	maxSize int
	flushCh chan struct{}
}

// NewDataBuffer 创建带 WAL 模式的 SQLite 持久化缓冲
func NewDataBuffer(dbPath string) (*DataBuffer, error) {
	// 确保目录存在
	dir := filepath.Dir(dbPath)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, fmt.Errorf("创建数据目录失败: %v", err)
	}

	db, err := sql.Open("sqlite3", dbPath+"?_journal=WAL&_synchronous=N")
	if err != nil {
		return nil, err
	}

	// 关键配置：WAL 模式 + 异步 checkpoint
	_, err = db.Exec(`
		PRAGMA journal_mode=WAL;
		PRAGMA synchronous=NORMAL;
		PRAGMA wal_autocheckpoint=1000;
		PRAGMA cache_size=-2000;
	`)
	if err != nil {
		return nil, err
	}

	// 创建时序数据表
	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS telemetry (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			timestamp REAL NOT NULL,
			device_id TEXT NOT NULL,
			topic TEXT NOT NULL,
			value TEXT NOT NULL,
			quality INTEGER DEFAULT 0,
			seq_num INTEGER DEFAULT 0,
			synced INTEGER DEFAULT 0
		);
		CREATE INDEX IF NOT EXISTS idx_ts ON telemetry(timestamp);
		CREATE INDEX IF NOT EXISTS idx_sync ON telemetry(synced, timestamp);
	`)
	if err != nil {
		return nil, err
	}

	buffer := &DataBuffer{
		db:      db,
		maxSize: 5000,
		flushCh: make(chan struct{}, 1),
	}

	// 启动批量写入协程
	go buffer.autoFlush()

	log.Printf("[Buffer] SQLite 持久化已启用: %s (WAL 模式)", dbPath)
	return buffer, nil
}

// Write 批量写入数据（线程安全）
func (b *DataBuffer) Write(records [][]interface{}) error {
	b.mu.Lock()
	defer b.mu.Unlock()

	b.batch = append(b.batch, records...)

	// 达到阈值或定时器触发时 flush
	if len(b.batch) >= b.maxSize {
		select {
		case b.flushCh <- struct{}{}:
		default:
		}
	}

	return nil
}

// autoFlush 自动批量提交，减少磁盘 I/O 次数
func (b *DataBuffer) autoFlush() {
	ticker := time.NewTicker(50 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			b.flush()
		case <-b.flushCh:
			b.flush()
		}
	}
}

// flush 执行批量 INSERT，使用 REPLACE INTO 避免重复
func (b *DataBuffer) flush() {
	b.mu.Lock()
	if len(b.batch) == 0 {
		b.mu.Unlock()
		return
	}

	batch := b.batch
	b.batch = nil
	b.mu.Unlock()

	tx, err := b.db.Begin()
	if err != nil {
		log.Printf("[Buffer] 事务开启失败: %v", err)
		return
	}

	stmt, err := tx.Prepare(`
		INSERT OR REPLACE INTO telemetry 
		(timestamp, device_id, topic, value, quality, seq_num, synced)
		VALUES (?, ?, ?, ?, ?, ?, 0)
	`)
	if err != nil {
		tx.Rollback()
		return
	}
	defer stmt.Close()

	for _, record := range batch {
		_, err := stmt.Exec(record...)
		if err != nil {
			log.Printf("[Buffer] 写入失败: %v", err)
			tx.Rollback()
			return
		}
	}

	if err := tx.Commit(); err != nil {
		log.Printf("[Buffer] 提交失败: %v", err)
	} else {
		log.Printf("[Buffer] 批量写入 %d 条记录", len(batch))
	}
}

