## 三、工业级生产环境完整实现代码示例

以下代码来自码视野边缘网关 v3.2 生产版本，使用 Go 编写，集成 SQLite（github.com/mattn/go-sqlite3）与 Modbus 驱动。

### 3.1 核心持久化层：带续传标记的数据写入

```go
package edge

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"time"

	_ "github.com/mattn/go-sqlite3"
)

// TelemetryRecord 表示一条带完整上下文的上报数据
// seq_id 为本地单调递增序列号，用于去重与排序
type TelemetryRecord struct {
	DeviceID string    `json:"device_id"`
	Ts       time.Time `json:"ts"`         // 采集时刻（本地时钟）
	SeqID    uint64    `json:"seq_id"`     // 本地单调序列，永不重复
	Tags     string    `json:"tags"`       // JSON 格式测点数据
	Checksum string    `json:"checksum"`   // 原始报文 CRC，用于服务端校验
	Status   int       `json:"status"`     // 0=待上报 1=已上报 2=上报失败重试
}

// PersistEngine 封装 SQLite 持久化逻辑，支持 WAL 模式
type PersistEngine struct {
	db        *sql.DB
	seqCounter uint64
	mu        chan struct{} // 轻量读写信号，避免频繁锁
}

// NewPersistEngine 初始化引擎，开启 WAL 模式 + 外键约束
func NewPersistEngine(dbPath string) (*PersistEngine, error) {
	// 关键：WAL 模式允许读而不阻塞写，对实时采集至关重要
	// _journal_mode=WAL 确保并发写入不产生磁盘 I/O 抖动
	connStr := fmt.Sprintf("%s?_journal_mode=WAL&_foreign_keys=ON&_busy_timeout=5000", dbPath)
	db, err := sql.Open("sqlite3", connStr)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}

	// 开启同步模式为 NORMAL，在持久化与安全之间取平衡
	// FULL 模式过于保守，会显著拖慢写入吞吐
	db.Exec("PRAGMA synchronous = NORMAL")
	// 设置 cache_size 为 64MB，减少磁盘刷盘频率
	db.Exec("PRAGMA cache_size = -65536")
	// mmap 大小 256MB，提升读取性能
	db.Exec("PRAGMA mmap_size = 268435456")

	// 建表：索引覆盖 ts+status 用于排序查询，seq_id 唯一约束防止重复
	createSQL := `
	CREATE TABLE IF NOT EXISTS telemetry (
		id          INTEGER PRIMARY KEY AUTOINCREMENT,
		device_id   TEXT NOT NULL,
		ts          INTEGER NOT NULL,      -- unix 毫秒
		seq_id      INTEGER UNIQUE NOT NULL,
		tags        TEXT NOT NULL,
		checksum    TEXT,
		status      INTEGER DEFAULT 0,     -- 0=pending 1=acked 2=failed
		created_at  INTEGER DEFAULT (unixepoch())
	);
	CREATE INDEX IF NOT EXISTS idx_telemetry_status_ts 
		ON telemetry(status, ts);
	CREATE INDEX IF NOT EXISTS idx_telemetry_device_seq 
		ON telemetry(device_id, seq_id);
	`
	if _, err := db.Exec(createSQL); err != nil {
		return nil, fmt.Errorf("create table: %w", err)
	}

	// 读取最后一条 seq_id，保证重启后单调递增不重复
	var lastSeq uint64
	row := db.QueryRow("SELECT COALESCE(MAX(seq_id), 0) FROM telemetry WHERE status != 1")
	row.Scan(&lastSeq)

	return &PersistEngine{
		db:         db,
		seqCounter: lastSeq,
		mu:         make(chan struct{}, 1),
	}, nil
}

// Write 原子写入一条遥测数据，带事务保护
// 核心逻辑：先用 SQLite 事务写入，再更新序列号，任何一步失败均回滚
func (e *PersistEngine) Write(rec TelemetryRecord) error {
	// 获取信号量，防止高并发下 seqCounter 竞态
	select {
	case e.mu <- struct{}{}:
	default:
		return fmt.Errorf("engine busy, drop record seq=%d", rec.SeqID)
	}
	defer func() { <-e.mu }()

	rec.Ts = time.Now()
	e.seqCounter++
	rec.SeqID = e.seqCounter

	tx, err := e.db.Begin()
	if err != nil {
		return fmt.Errorf("begin tx: %w", err)
	}

	stmt, err := tx.Prepare(`
		INSERT INTO telemetry (device_id, ts, seq_id, tags, checksum, status)
		VALUES (?, ?, ?, ?, ?, 0)
	`)
	if err != nil {
		tx.Rollback()
		return err
	}
	defer stmt.Close()

	_, err = stmt.Exec(rec.DeviceID, rec.Ts.UnixMilli(), rec.SeqID,
		rec.Tags, rec.Checksum)
	if err != nil {
		tx.Rollback()
		return fmt.Errorf("insert record: %w", err)
	}

	if err = tx.Commit(); err != nil {
		return fmt.Errorf("commit tx: %w", err)
	}

	log.Printf("[edge] persisted seq=%d device=%s ts=%s",
		rec.SeqID, rec.DeviceID, rec.Ts.Format("15:04:05.000"))
	return nil
}

// FetchPendingBatch 按 ts 升序取出最多 limit 条待上报记录
// 返回前先将状态标记为 2（重试中），防止重复取出
func (e *PersistEngine) FetchPendingBatch(limit int) ([]TelemetryRecord, uint64, error) {
	tx, err := e.db.Begin()
	if err != nil {
		return nil, 0, err
	}
	defer tx.Rollback()

	// UPDATE ... RETURNING 一次性完成标记，原子性强
	rows, err := tx.Query(`
		UPDATE telemetry 
		SET status = 2 
		WHERE status = 0 
		ORDER BY ts ASC, seq_id ASC 
		LIMIT ? 
		RETURNING id, device_id, ts, seq_id, tags, checksum, status
	`)
	if err != nil {
		// 部分数据库驱动不支持 RETURNING，回退为两步查询
		rows, err = e.fetchWithFallback(tx, limit)
		if err != nil {
			return nil, 0, err
		}
	}
	defer rows.Close()

	var records []TelemetryRecord
	var maxSeqID uint64
	for rows.Next() {
		var rec TelemetryRecord
		var tsUnix int64
		if err := rows.Scan(&rec.ID, &rec.DeviceID, &tsUnix,
			&rec.SeqID, &rec.Tags, &rec.Checksum, &rec.Status); err != nil {
			return nil, 0, err
		}
		rec.Ts = time.Unix(tsUnix, 0)
		records = append(records, rec)
		if rec.SeqID > maxSeqID {
			maxSeqID = rec.SeqID
		}
	}

	if err = tx.Commit(); err != nil {
		return nil, 0, err
	}
	return records, maxSeqID, nil
}

func (e *PersistEngine) fetchWithFallback(tx *sql.Tx, limit int) (*sql.Rows, error) {
	rows, err := tx.Query(`
		SELECT id, device_id, ts, seq_id, tags, checksum, status
		FROM telemetry 
		WHERE status = 0 
		ORDER BY ts ASC, seq_id ASC 
		LIMIT ?
	`, limit)
	if err != nil {
		return nil, err
	}
	// 再执行标记更新
	_, err = tx.Exec(`
		UPDATE telemetry SET status = 2
		WHERE id IN (SELECT id FROM telemetry 
		             WHERE status = 0 ORDER BY ts, seq_id LIMIT ?)
	`, limit)
	return rows, err
}

// MarkAsAcked 上报成功后调用，清理已确认记录
func (e *PersistEngine) MarkAsAcked(maxSeqID uint64) error {
	result, err := e.db.Exec(
		"DELETE FROM telemetry WHERE status = 1 OR (status = 2 AND seq_id <= ?)",
		maxSeqID,
	)
	if err != nil {
		return err
	}
	affected, _ := result.RowsAffected()
	log.Printf("[edge] acked and cleaned %d records up to seq=%d", affected, maxSeqID)
	return nil
}

// PendingCount 返回待上报数量，用于监控告警
func (e *PersistEngine) PendingCount() (int, error) {
	var count int
	err := e.db.QueryRow("SELECT COUNT(*) FROM telemetry WHERE status = 0").Scan(&count)
	return count, err
}
