## 三、工业级生产环境完整实现代码示例

以下为基于Go语言的边缘网关核心模块实现，包含串口驱动、帧解析、本地缓存与MQTT上送完整链路。

### 3.1 多路串口采集调度器（带重试与超时控制）

```go
package gateway

import (
	"fmt"
	"log"
	"sync"
	"time"

	"github.com/tarm/goserial"
	"github.com/eclipse/paho.mqtt.go"
)

// ModbusDevice 表示一个Modbus从站设备
type ModbusDevice struct {
	Port      string        // 串口号，如 /dev/ttyUSB0
	BaudRate  int           // 波特率
	Timeout   time.Duration // 单次请求超时
	RetryCnt  int           // 最大重试次数
	RegStart  uint16        // 寄存器起始地址
	RegCount  uint16        // 读取寄存器数量
}

// EdgeGateway 边缘网关核心结构体
type EdgeGateway struct {
	devices []*ModbusDevice
	mux     sync.Mutex
	client  mqtt.Client
	cache   *LocalStorage // 本地SQLite缓存
	config  GatewayConfig
}

// PollLoop 主轮询循环，包含指数退避重试
func (g *EdgeGateway) PollLoop(ctx context.Context) {
	for _, dev := range g.devices {
		go g.pollDevice(ctx, dev)
	}
}

func (g *EdgeGateway) pollDevice(ctx context.Context, dev *ModbusDevice) {
	ticker := time.NewTicker(g.config.PollInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			data, err := g.readModbusFrame(dev)
			if err != nil {
				// 记录错误并尝试重传
				g.handleError(dev, err)
				continue
			}
			// 写入本地缓存（先落盘，再异步上送）
			g.cache.Save(dev, data)
			g.publishToMQTT(dev, data)
		}
	}
}

// readModbusFrame 带重试的Modbus RTU读取，含1.5字符间隔等待
func (g *EdgeGateway) readModbusFrame(dev *ModbusDevice) ([]byte, error) {
	port, err := serial.OpenPort(&serial.Config{
		Name:        dev.Port,
		Baud:        dev.BaudRate,
		ReadTimeout: dev.Timeout,
	})
	if err != nil {
		return nil, fmt.Errorf("打开串口 %s 失败: %w", dev.Port, err)
	}
	defer port.Close()

	var lastErr error
	for attempt := 0; attempt <= dev.RetryCnt; attempt++ {
		// 构建Modbus RTU读保持寄存器请求帧 (功能码0x03)
		req := buildModbusReadRequest(dev.RegStart, dev.RegCount)

		n, err := port.Write(req)
		if err != nil || n != len(req) {
			lastErr = fmt.Errorf("写串口失败: %w", err)
			time.Sleep(time.Duration(attempt+1) * 100 * time.Millisecond)
			continue
		}

		// 等待1.5个字符时间（9600bps时约1.56ms），确保从站响应就绪
		time.Sleep(charTime(dev.BaudRate, 1.5))

		resp := make([]byte, maxResponseSize)
		n, err = port.Read(resp)
		if err != nil {
			lastErr = err
			continue
		}

		// CRC校验
		if !verifyCRC(resp[:n]) {
			lastErr = fmt.Errorf("CRC校验失败，丢弃帧")
			continue
		}

		return resp[:n], nil
	}

	return nil, fmt.Errorf("重试%d次后仍失败: %w", dev.RetryCnt, lastErr)
}

// charTime 计算单个字符在指定波特率下的传输时间（毫秒）
func charTime(baudrate int, chars float64) time.Duration {
	// 10位/字符（1起始+8数据+1停止，无校验）
	return time.Duration(float64(chars*10.0/baudrate)*1000) * time.Millisecond
}
```

### 3.2 本地持久化缓存层（SQLite + Ring Buffer）

```go
package gateway

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"time"

	_ "github.com/mattn/go-sqlite3"
)

// LocalStorage 本地SQLite时序缓存，使用WAL模式提升并发写入性能
type LocalStorage struct {
	db *sql.DB
}

func NewLocalStorage(path string) (*LocalStorage, error) {
	db, err := sql.Open("sqlite3", path+"?_journal=WAL&_timeout=5000")
	if err != nil {
		return nil, err
	}
	// 创建时序表
	_, err = db.Exec(`
		CREATE TABLE IF NOT EXISTS telemetry (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			timestamp TEXT NOT NULL,
			device_port TEXT NOT NULL,
			register_address INTEGER NOT NULL,
			value REAL NOT NULL,
			unit TEXT,
			queue_order INTEGER DEFAULT 0
		);
		CREATE INDEX IF NOT EXISTS idx_ts ON telemetry(timestamp);
	`)
	return &LocalStorage{db: db}, err
}

// Save 持久化单条测点数据
func (ls *LocalStorage) Save(dev *ModbusDevice, frame []byte) error {
	tags := parseModbusFrame(frame) // 解析为key-value对
	ts := time.Now().UTC().Format(time.RFC3339)

	tx, _ := ls.db.Begin()
	for reg, val := range tags {
		_, err := tx.Exec(
			"INSERT INTO telemetry (timestamp, device_port, register_address, value, unit) VALUES (?, ?, ?, ?, ?)",
			ts, dev.Port, reg, val, "raw",
		)
		if err != nil {
			tx.Rollback()
			return err
		}
	}
	return tx.Commit()
}

// DrainPending 网络恢复后批量上送积压数据，按时间戳排序
func (ls *LocalStorage) DrainPending(limit int) ([]TelemetryBatch, error) {
	rows, err := ls.db.Query(
