### 3.3 MQTT QoS1 发布与断网续传

```go
func (g *EdgeGateway) publishToMQTT(dev *ModbusDevice, frame []byte) {
	if !g.client.IsConnected() {
		// 未连接时仅落盘，不在内存堆积
		log.Printf("MQTT未连接，数据已缓存至本地: %s", dev.Port)
		return
	}

	// 构造MQTT Topic: gateway/{port}/{register}
	topic := fmt.Sprintf("gateway/%s/%d", dev.Port, dev.RegStart)
	payload, _ := json.Marshal(map[string]interface{}{
		"ts":    time.Now().Unix(),
		"frame": frame,
	})

	// QoS1保证至少一次投递，Retain=true让新订阅者能立即获取最新值
	token := g.client.Publish(topic, 1, true, payload)
	token.Wait()
}
```

